"""Customer insight endpoints for the account team."""

from __future__ import annotations

from typing import Any

from orders.application.errors import CustomerNotFound
from orders.application.order_service import OrderService
from orders.controllers.http import InvalidRequest, Response, bad_request, not_found, require_positive_int
from orders.domain.customers import Customer
from orders.domain.orders import OrderSummary


def history_entry(summary: OrderSummary) -> dict[str, Any]:
    return {"order_id": summary.order.order_id, "status": summary.order.status,
            "total_cents": summary.total_cents}


def leaderboard_entry(customer: Customer, lifetime_value_cents: int) -> dict[str, Any]:
    return {"customer_id": customer.customer_id, "name": customer.name,
            "lifetime_value_cents": lifetime_value_cents}


class CustomerInsightsController:
    def __init__(self, orders: OrderService) -> None:
        self._orders = orders

    def handle_order_history(self, customer_id: str) -> Response:
        """Every order for a customer, newest first, with its total after discount."""
        try:
            summaries = self._orders.order_history(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id,
                              "orders": [history_entry(s) for s in summaries]})

    def handle_lifetime_value(self, customer_id: str) -> Response:
        """Count and total of a customer's orders, leaving out cancelled ones."""
        try:
            order_count, lifetime_value_cents = self._orders.lifetime_value(customer_id)
        except CustomerNotFound:
            return not_found("customer")
        return Response(200, {"customer_id": customer_id, "order_count": order_count,
                              "lifetime_value_cents": lifetime_value_cents})

    def handle_top_customers(self, limit: Any) -> Response:
        """Customers with the highest lifetime value, at most ``limit`` of them."""
        try:
            count = require_positive_int(limit, "limit")
        except InvalidRequest as exc:
            return bad_request(exc)
        ranked = self._orders.top_customers(count)
        return Response(200, {"customers": [leaderboard_entry(c, value) for c, value in ranked]})

    def handle_customers_without_orders(self) -> Response:
        """Registered customers who have no orders that are not cancelled, in registration order."""
        customers = self._orders.customers_without_orders()
        return Response(200, {"customers": [contact_entry(c) for c in customers]})

